-- Esquema PostgreSQL / Supabase (referencia para migrar desde SQLite)
create extension if not exists citext;
CREATE TABLE companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),legal_name text NOT NULL,tax_id text UNIQUE NOT NULL);
CREATE TABLE users(id uuid PRIMARY KEY REFERENCES auth.users,full_name text NOT NULL,email citext UNIQUE NOT NULL);
CREATE TABLE user_company_access(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,company_id uuid NOT NULL REFERENCES companies ON DELETE CASCADE,role text NOT NULL CHECK(role IN('admin','treasury','viewer')),screens text[] NOT NULL DEFAULT '{}',UNIQUE(user_id,company_id));
CREATE TABLE banks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,kind text DEFAULT 'BANK');
CREATE TABLE credit_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,name text NOT NULL,note text);
CREATE TABLE credit_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies,bank_id uuid NOT NULL REFERENCES banks,credit_type_id uuid NOT NULL REFERENCES credit_types,collection_concept text NOT NULL,status text NOT NULL DEFAULT 'VIG',alias text NOT NULL,contract_no text NOT NULL,charge_account text,amount numeric(18,2) NOT NULL CHECK(amount>0),bullet numeric(18,2) NOT NULL DEFAULT 0,installments int,start_date date NOT NULL,end_date date NOT NULL,review_date date,spread numeric(9,6) NOT NULL DEFAULT 0,UNIQUE(company_id,alias),CHECK(end_date>start_date),CHECK(bullet<amount));
CREATE TABLE banxico_rates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),credit_line_id uuid NOT NULL REFERENCES credit_lines ON DELETE CASCADE,rate_date date NOT NULL,rate numeric(9,6) NOT NULL,source text DEFAULT 'MANUAL',UNIQUE(credit_line_id,rate_date));
CREATE TABLE amortization_schedule(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),credit_line_id uuid NOT NULL REFERENCES credit_lines ON DELETE CASCADE,seq int NOT NULL,period_start date,payment_date date,final_rate numeric(9,6),payment numeric(18,2),balance numeric(18,2),omex_interest numeric(18,2),bank_interest numeric(18,2),diff numeric(18,2) GENERATED ALWAYS AS(coalesce(bank_interest,0)-coalesce(omex_interest,0)) STORED,UNIQUE(credit_line_id,seq));
CREATE TABLE account_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),credit_line_id uuid NOT NULL REFERENCES credit_lines ON DELETE CASCADE,movement_date date NOT NULL,kind char(1) CHECK(kind IN('C','A')),amount numeric(18,2) NOT NULL CHECK(amount>0),reference text);
